/* one mutex per aggregate root, entries created under the registry lock */
pthread_mutex_t *lk = registry_lock_for(root_id);
pthread_mutex_lock(lk);
cluster_apply(root_id, edit_fn);   /* root + members, one lock */
pthread_mutex_unlock(lk);

/* database side, SQLite: no second writer once this returns */
sqlite3_exec(db, "BEGIN IMMEDIATE", 0, 0, 0);
